describe('Add and Remove Product from Cart', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should successfully add and remove a product from cart and update badge', () => {
    // Login with standard user
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Verify login success
    cy.get('[data-testid="inventory-container"]').should('be.visible');
    cy.get('[data-testid="inventory-list"]').should('be.visible');

    // Add product to cart
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();

    // Verify cart badge updates to 1
    cy.get('[data-testid="shopping-cart-badge"]').should('contain', '1');
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').should('contain', 'Remove');

    // Remove product from cart
    cy.get('[data-testid="remove-sauce-labs-backpack"]').click();

    // Verify cart badge updates to 0
    cy.get('[data-testid="shopping-cart-badge"]').should('contain', '0');
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').should('contain', 'Add to cart');
  });

  it('should handle multiple items in cart and remove one item', () => {
    // Login with standard user
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Add first product
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-testid="shopping-cart-badge"]').should('contain', '1');

    // Add second product
    cy.get('[data-testid="add-to-cart-sauce-labs-bike-light"]').click();
    cy.get('[data-testid="shopping-cart-badge"]').should('contain', '2');

    // Verify both items are in cart
    cy.get('[data-testid="inventory-item-sauce-labs-backpack-img"]').should('be.visible');
    cy.get('[data-testid="inventory-item-sauce-labs-bike-light-img"]').should('be.visible');

    // Remove first product
    cy.get('[data-testid="remove-sauce-labs-backpack"]').click();

    // Verify cart badge updates to 1
    cy.get('[data-testid="shopping-cart-badge"]').should('contain', '1');

    // Verify second item remains in cart
    cy.get('[data-testid="inventory-item-sauce-labs-bike-light-img"]').should('be.visible');
    cy.get('[data-testid="add-to-cart-sauce-labs-bike-light"]').should('contain', 'Remove');
  });
});
